import{_ as o,o as n,c as i,j as e,a as t,aa as r}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/firstofall/en_spravadomen.png",l="/buildary-help-preview/media/cs/diary/btn_domena.png",d="/buildary-help-preview/media/en/firstofall/en_spravadomen3.png",c="/buildary-help-preview/media/en/firstofall/en_btn_nova_domena.png",m="/buildary-help-preview/media/en/firstofall/en_novadomena.png",p="/buildary-help-preview/media/en/firstofall/en_uzivateledomeny.png",u="/buildary-help-preview/media/en/firstofall/en_btn_pridat.png",h="/buildary-help-preview/media/cs/diary/btn_edit.png",x=JSON.parse('{"title":"Domain","description":"","frontmatter":{"title":"Domain","wiki":"en:firstofall:domain"},"headers":[],"relativePath":"en/firstofall/domain.md","filePath":"en/firstofall/domain.md","lastUpdated":1795418601000}'),g={name:"en/firstofall/domain.md"};function y(f,a,w,_,b,v){return n(),i("div",null,[...a[0]||(a[0]=[e("h1",{id:"domain",tabindex:"-1"},[t("Domain "),e("a",{class:"header-anchor",href:"#domain","aria-label":'Permalink to "Domain"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/EpqdNLNExLo",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),r('<p>The concept of <strong>Domain</strong> was introduced in Buildary to allow projects belonging to the same customer to be managed under one umbrella and to create shared settings for these projects. Domains are primarily relevant for corporate customers. Most Buildary users will either not encounter the concept of a domain at all or will only encounter it occasionally. Every user who accesses <strong>Buildary</strong> for the first time is given a personal domain. Within this domain, they have full permissions and their work is not restricted in any way. For companies, we strongly recommend creating a corporate domain. Any user can create a domain and thereby become its owner. This gives them certain rights described in a separate chapter.</p><h2 id="creating-and-configuring-a-domain" tabindex="-1">Creating and Configuring a Domain <a class="header-anchor" href="#creating-and-configuring-a-domain" aria-label="Permalink to &quot;Creating and Configuring a Domain&quot;">​</a></h2><figure class="shot" style="--w:200px;"><img src="'+s+'" alt="Domain Management option in the menu in the upper-right corner of the screen" width="200" loading="lazy"></figure><p>When should you create a domain? Create a domain if you want to work in Buildary as a company that has its own projects and its own users.</p><p>If you only work on projects that someone has invited you to, or if you have an individual project (for example, your own family home), your personal domain is sufficient and you do not need to create a corporate domain.</p><p>A domain is created using the <strong>Domain Settings</strong> option in the left panel <img src="'+l+'" alt="Domain Management" data-no-zoom loading="lazy">.</p><figure class="shot" style="--w:600px;"><img src="'+d+'" alt="Domain Management Window" loading="lazy"></figure><p>Your personal domain will always be displayed in the first row of the window. We recommend keeping your personal domain for testing and creating a separate domain for your company. A new domain is created using the <img src="'+c+'" alt="+ New Domain" data-no-zoom loading="lazy"> button.</p><figure class="shot" style="--w:600px;"><img src="'+m+'" alt="New Domain Window" width="1200" loading="lazy"></figure><p>In the <strong>New Domain</strong> window, you can enter the domain name, the company&#39;s identification details, and specify whether the company is generally a client or a contractor. This is only default information and can be adjusted individually for each project.</p><p>When a new Domain is created, the First company logo is used by default. You can delete this logo or replace it with your company&#39;s logo. Since the logo will be displayed on a dark background, we recommend using a white or very light-colored logo. The logo configured in the Domain will be used as the Logo on the left in every newly created Project Diary and will be displayed in the application and in PDF reports.</p><h2 id="domain-users" tabindex="-1">Domain Users <a class="header-anchor" href="#domain-users" aria-label="Permalink to &quot;Domain Users&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+p+'" alt="Domain Settings Window" width="600" loading="lazy"></figure><p>Use the <img src="'+u+'" alt="+ Add" data-no-zoom loading="lazy"> button to add a new Domain User. To edit a user, click the edit icon <img src="'+h+'" alt="Edit Icon" data-no-zoom loading="lazy">. You can assign the appropriate permissions to users in the domain.</p><p>The <strong>Domain Details</strong> window contains the following tabs:</p><ul><li><strong>Domain Management</strong> - you can edit the domain details or update the company&#39;s identification details.</li><li><strong>Domain Users</strong> - you can add and edit users here. Only add users from your own company to the domain. Users from external companies should be invited to specific projects and therefore should not be part of your domain.</li><li><strong>User Reports</strong> - you can export XLS reports showing users by project, the number of licenses in use, or a list of projects. You can also replace one user with another on this tab.</li><li><strong>Domain Billing</strong> - this section contains all automatically generated documents issued by us for application operation and archiving, including Payment Requests and Tax Documents.</li><li><strong>Attendance Settings</strong> - connect the attendance systems that diaries import people on site from. See <a href="/buildary-help-preview/en/diary/attendance_system">Project Attendance System</a>.</li></ul>',16)])])}const T=o(g,[["render",y]]);export{x as __pageData,T as default};
